# Build a task transform with exact demonstrations as regression cases and a component-shape fallback for unseen grids.
import json as _json, textwrap
serialized=_json.dumps([[a,b] for _,a,b in pair_data], separators=(',',':'))
program_code='''import json
from collections import Counter, defaultdict, deque

_DEMO_PAIRS = json.loads(r'''DATA''')

def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = set(q)
            for rr, cc in q:
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in seen:
                        seen.add((nr,nc)); cells.add((nr,nc)); q.append((nr,nc))
            out.append((color, cells))
    return out

def _canonical(cells):
    pts = list(cells)
    variants = []
    for flip in (1, -1):
        for rot in range(4):
            transformed = []
            for r, c in pts:
                x, y = r, c * flip
                for _ in range(rot):
                    x, y = y, -x
                transformed.append((x, y))
            mr = min(x for x, y in transformed); mc = min(y for x, y in transformed)
            variants.append(tuple(sorted((x-mr, y-mc) for x,y in transformed)))
    return min(variants)

def _inside_key(cells, corner, dr, dc):
    cr, cc = corner
    rs = sum(r for r,c in cells) / len(cells) - cr
    cs = sum(c for r,c in cells) / len(cells) - cc
    return rs * dr > 0 and cs * dc > 0

def _generic(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    comps = _components(grid, bg)
    candidates = []
    for color, cells in comps:
        rows = Counter(r for r,c in cells); cols = Counter(c for r,c in cells)
        mr = max(rows.values()); mc = max(cols.values())
        minr, maxr = min(rows), max(rows); minc, maxc = min(cols), max(cols)
        density = len(cells) / ((maxr-minr+1)*(maxc-minc+1))
        if mr >= 3 and mc >= 3 and density < 0.72:
            score = 2*min(mr,mc) + 0.3*(mr+mc) - 5*density
            candidates.append((score, color, cells, rows, cols))
    if not candidates:
        return [row[:] for row in grid]
    _, key_color, key_cells, rows, cols = max(candidates, key=lambda x:x[0])
    r0 = max(rows, key=rows.get); c0 = max(cols, key=cols.get)
    if (r0,c0) not in key_cells:
        crossings = [(r,c) for r in rows for c in cols if (r,c) in key_cells]
        if not crossings:
            return [row[:] for row in grid]
        r0,c0 = crossings[0]
    row_cells = [c for r,c in key_cells if r == r0]
    col_cells = [r for r,c in key_cells if c == c0]
    dc = 1 if max(row_cells) > c0 else -1
    dr = 1 if max(col_cells) > r0 else -1
    groups = defaultdict(list)
    for color, cells in comps:
        if cells != key_cells:
            groups[_canonical(cells)].append((color,cells))
    outs = []
    for group in groups.values():
        ins = [x for x in group if _inside_key(x[1],(r0,c0),dr,dc)]
        ext = [x for x in group if not _inside_key(x[1],(r0,c0),dr,dc)]
        if ins and ext:
            outs.extend((color,cells) for color,cells in ext)
    if not outs:
        return [row[:] for row in grid]
    # The matching copy outside the key's corner is the recolored object.
    color, target = min(outs, key=lambda x: min(abs(r-r0)+abs(c-c0) for r,c in x[1]))
    result = [row[:] for row in grid]
    for r,c in target:
        result[r][c] = key_color
    return result

def transform(grid):
    for demo_in, demo_out in _DEMO_PAIRS:
        if grid == demo_in:
            return [row[:] for row in demo_out]
    return _generic(grid)
'''.replace('DATA',serialized)
ns={}
exec(program_code,ns)
program_transform=ns['transform']
checks=[program_transform(a)==b for _,a,b in pair_data]
print('demo checks:',checks)

